CREATE TABLE qas_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,asset_code text NOT NULL,name text NOT NULL,category text NOT NULL DEFAULT 'equipment',asset_type text NOT NULL DEFAULT 'asset',serial_no text,model text,manufacturer text,purchase_date date,purchase_cost numeric(20,2),supplier_ref uuid,accounting_asset_ref uuid,inventory_item_ref uuid,location_ref uuid,custodian_ref uuid,status text NOT NULL DEFAULT 'available',condition text NOT NULL DEFAULT 'good',metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),retired_at timestamptz,UNIQUE(org_id,asset_code));
CREATE INDEX qas_assets_org_idx ON qas_assets(org_id,status,category);
CREATE TABLE qas_asset_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,asset_id uuid NOT NULL REFERENCES qas_assets(id),assignment_no text NOT NULL,assigned_to_ref uuid NOT NULL,assigned_to_type text NOT NULL DEFAULT 'employee',from_location_ref uuid,to_location_ref uuid,purpose text,assigned_by uuid,assigned_at timestamptz NOT NULL DEFAULT now(),due_at timestamptz,status text NOT NULL DEFAULT 'active',return_condition text,returned_by uuid,returned_at timestamptz,transfer_to_ref uuid,transfer_at timestamptz,idempotency_key text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,assignment_no),UNIQUE(org_id,idempotency_key));
CREATE INDEX qas_asset_assignments_org_idx ON qas_asset_assignments(org_id,asset_id,status);
CREATE TABLE qas_asset_transfers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,asset_id uuid NOT NULL REFERENCES qas_assets(id),from_holder_ref uuid,to_holder_ref uuid,from_location_ref uuid,to_location_ref uuid,reason text,requested_by uuid,approved_by uuid,transferred_at timestamptz NOT NULL DEFAULT now(),assignment_id uuid REFERENCES qas_asset_assignments(id),idempotency_key text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,idempotency_key));
CREATE INDEX qas_asset_transfers_org_idx ON qas_asset_transfers(org_id,asset_id);
CREATE TABLE qas_vehicles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,asset_id uuid NOT NULL REFERENCES qas_assets(id),plate_no text NOT NULL,vehicle_type text NOT NULL DEFAULT 'car',vin text,engine_no text,fuel_type text,registration_expiry date,insurance_expiry date,odometer numeric(20,2) NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'available',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,plate_no),UNIQUE(org_id,asset_id));
CREATE INDEX qas_vehicles_org_idx ON qas_vehicles(org_id,status);
CREATE TABLE qas_usage_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,asset_id uuid NOT NULL REFERENCES qas_assets(id),vehicle_id uuid REFERENCES qas_vehicles(id),used_by_ref uuid,usage_type text NOT NULL DEFAULT 'operation',started_at timestamptz NOT NULL DEFAULT now(),ended_at timestamptz,odometer_start numeric(20,2),odometer_end numeric(20,2),quantity numeric(20,4),unit text,note text,idempotency_key text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,idempotency_key));
CREATE INDEX qas_usage_logs_org_idx ON qas_usage_logs(org_id,asset_id,started_at);
CREATE TABLE qas_maintenance_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,asset_id uuid NOT NULL REFERENCES qas_assets(id),vehicle_id uuid REFERENCES qas_vehicles(id),order_no text NOT NULL,kind text NOT NULL DEFAULT 'maintenance',priority text NOT NULL DEFAULT 'normal',description text NOT NULL,status text NOT NULL DEFAULT 'open',vendor_ref uuid,estimated_cost numeric(20,2),actual_cost numeric(20,2),scheduled_at timestamptz,started_at timestamptz,completed_at timestamptz,reported_by uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,order_no));
CREATE INDEX qas_maintenance_orders_org_idx ON qas_maintenance_orders(org_id,asset_id,status);
CREATE TABLE qas_inspections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,asset_id uuid NOT NULL REFERENCES qas_assets(id),vehicle_id uuid REFERENCES qas_vehicles(id),inspection_no text NOT NULL,inspection_type text NOT NULL DEFAULT 'routine',inspected_by uuid,inspected_at timestamptz NOT NULL DEFAULT now(),result text NOT NULL DEFAULT 'pass',findings jsonb NOT NULL DEFAULT '{}'::jsonb,next_due_at timestamptz,status text NOT NULL DEFAULT 'recorded',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,inspection_no));
CREATE INDEX qas_inspections_org_idx ON qas_inspections(org_id,asset_id,result);
CREATE TABLE qas_incidents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,asset_id uuid NOT NULL REFERENCES qas_assets(id),vehicle_id uuid REFERENCES qas_vehicles(id),incident_no text NOT NULL,reported_by uuid,occurred_at timestamptz NOT NULL DEFAULT now(),severity text NOT NULL DEFAULT 'minor',description text NOT NULL,status text NOT NULL DEFAULT 'open',maintenance_order_id uuid REFERENCES qas_maintenance_orders(id),resolution text,resolved_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,incident_no));
CREATE INDEX qas_incidents_org_idx ON qas_incidents(org_id,asset_id,status);
